fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    let mut result = Vec::with_capacity(v1.len() + v2.len());
    result.extend(v1.iter());
    result.extend(v2.iter());
    result
}

fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    let first_slice = &first[..first.len() - 1]; // Take all but the last element of first
    append_vectors(first_slice, second)
}

// Example usage
fn main() {
    let a = vec![1, 2, 3, 4];
    let b = vec![5, 6, 7];
    
    let result = replace_last_element(&a, &b);
    println!("{:?}", result); // Output: [1, 2, 3, 5, 6, 7]
}